macro.encore_analytics.exclude_dlt_colum.macro_sql:
{% macro exclude_dlt_columns(relation) %}
{#
    dlt only adds _dlt_load_id/_dlt_id sometimes (depends on the backend/load
    path), so excluding them by name breaks on tables where they don't exist.
    Check what's actually there instead.
#}
    {% set existing_cols = [] %}
    {% if execute %}
        {% set cols = adapter.get_columns_in_relation(relation) %}
        {% for col in cols %}
            {% if col.name.lower() in ['_dlt_load_id', '_dlt_id'] %}
                {% do existing_cols.append(col.name) %}
            {% endif %}
        {% endfor %}
    {% endif %}
    {%- if existing_cols -%}
exclude ({{ existing_cols | join(', ') }})
    {%- endif -%}
{% endmacro %}
